@dataclass
class OverlayContext:
    """Rendering context passed to overlay renderers."""
    terrain: 'Terrain'
    grid: 'HexGrid'
    builder: 'SVGBuilder'
    c2f: dict = None
    extras: dict = field(default_factory=dict)

    def __getattr__(self, name):
        extras = self.__dict__.get('extras', {})
        if name in extras: return extras[name]
        raise AttributeError(f"OverlayContext has no '{name}' — did you forget to pass it?")

    @property
    def available(self):
        keys = {'terrain', 'grid', 'builder'}
        if self.c2f is not None: keys.add('c2f')
        keys |= {k for k, v in self.extras.items() if v is not None}
        return keys

    @classmethod
    def from_terrain(cls, terrain, *, region=None, padding=1, radius=None, **extras):
        """Build context with zoom/radius handling."""
        coarse_basins = None
        basins = extras.get('basins')
        c2f = extras.pop('c2f', None)

        if region is not None:
            if basins is not None:
                coarse_basins = basins
                extras['basins'] = None
            terrain = terrain.zoom(region, padding=padding)
            if c2f is None:
                c2f = getattr(terrain, 'c2f', None)

        grid = terrain.hexGrid
        if radius: grid.adjustRadius(radius)

        # Auto-extract from result
        result = extras.get('result')
        if extras.get('basins') is None and result and hasattr(result, 'basins'):
            extras['basins'] = result.basins
        if extras.get('soil') is None and result and hasattr(result, 'soil'):
            extras['soil'] = result.soil

        extras['coarse_basins'] = coarse_basins
        return cls(terrain=terrain, grid=grid, builder=grid.builder, c2f=c2f, extras=extras)

    def test(self, *overlays):
        """Run overlays with errors propagated — fail fast for debugging."""
        results = {}
        for o in sorted(overlays, key=lambda o: o.priority):
            missing = o.requires - self.available
            if missing:
                raise ValueError(f"'{o.name}' requires {missing} but context has {self.available}")
            svg = o.renderer(self)
            tag = f"SVG ({len(svg)} chars)" if svg else "style-only"
            print(f"  ✓ {o.name:20s} pri={o.priority:<4d} {tag}")
            results[o.name] = svg
        return results


    @property
    def is_zoomed(self):
        """True if rendering a zoomed-in region with coarse→fine mapping."""
        return self.c2f is not None

    def fine_indices(self, coarse_idx):
        """Coarse index → list of fine indices (empty if unmapped)."""
        if self.c2f is None: return [coarse_idx]
        val = self.c2f.get(coarse_idx)
        if val is None: return []
        return val if isinstance(val, list) else [val]

    def fine_first(self, coarse_idx):
        """Coarse index → first fine index, or -1 if unmapped."""
        mapped = self.fine_indices(coarse_idx)
        return mapped[0] if mapped else -1


