# Keys that get pulled into extras (not passed to the Div)
_CTX_KEYS = frozenset({
    'basins', 'soil', 'result', 'board', 'c2f',
    'coarse_basins', 'corridors', 'pieces', 'squads',
})

def TerrainDisplay(
    *overlays: OverlaySpec,
    ctx: OverlayContext = None,          # pre-built context
    terrain: 'Terrain' = None,           # OR build from terrain + extras
    region: 'HexRegion' = None,
    padding: int = 1,
    radius=None,
    context_cls=OverlayContext,
    debug=False,
    **kw
):
    # ── Separate context extras from HTML attrs ──
    extras = {k: kw.pop(k) for k in list(kw) if k in _CTX_KEYS}

    if ctx is None:
        if terrain is None:
            raise ValueError("Pass either ctx= or terrain=")
        ctx = context_cls.from_terrain(
            terrain, region=region, padding=padding, radius=radius, **extras
        )

    # ── Phase 1: Run renderers in priority order ──
    sorted_overlays = sorted(overlays, key=lambda o: o.priority)
    collected = []
    for spec in sorted_overlays:
        missing = spec.requires - ctx.available
        if missing:
            logging.warning(f"Skipping {spec.name}: missing {missing}")
            continue
        try:
            svg = spec.renderer(ctx)
            if svg: collected.append((spec.name, svg))
        except Exception as e:
            logging.error(f"Overlay {spec.name} failed: {e}")

    # ── Phase 2: Bake hex styles ──
    stylized_spec = next((s for s in sorted_overlays if s.stylized), None)
    if stylized_spec:
        f = stylized_spec.edge_fn or unique_windy_edge()
        hexes_svg = ctx.grid.styleLayer(f=f, smooth=True)
        ctx.builder.adjust("hexes", hexes_svg)
    else:
        ctx.grid.update()

    # ── Phase 3: Stack SVG overlay layers ──
    for name, svg in collected:
        ctx.builder.adjust(name, svg)

    if debug: return ctx.builder.__ft__()

    return Div(
        HexTouchMap(ctx.grid, cls=kw.pop('map_cls', 'w-full h-full')),
        **kw  # remaining are HTML/HTMX attrs
    )



