def join_paths(paths, tolerance=2.0):
    """Join connected MapPath segments into longer continuous paths."""
    if not paths: return paths
    
    remaining = list(paths)
    joined = []
    
    while remaining:
        current_pts = list(remaining.pop(0).points)
        changed = True
        
        while changed:
            changed = False
            for i, seg in enumerate(remaining):
                start, end = seg.points[0], seg.points[-1]
                cur_start, cur_end = current_pts[0], current_pts[-1]
                
                if cur_end.distance(start) < tolerance:
                    current_pts.extend(seg.points[1:])  # skip duplicate point
                    remaining.pop(i); changed = True; break
                elif cur_end.distance(end) < tolerance:
                    current_pts.extend(reversed(seg.points[:-1]))
                    remaining.pop(i); changed = True; break
                elif cur_start.distance(end) < tolerance:
                    current_pts = list(seg.points[:-1]) + current_pts
                    remaining.pop(i); changed = True; break
                elif cur_start.distance(start) < tolerance:
                    current_pts = list(reversed(seg.points[1:])) + current_pts
                    remaining.pop(i); changed = True; break
        
        joined.append(MapPath(points=current_pts, style=paths[0].style))
    
    return joined


