def offset_path(points, distance):
    """Offset a closed path by `distance` pixels using averaged vertex normals."""
    n = len(points)
    if n < 3: return points
    result = []
    for i in range(n):
        p_prev = points[(i - 1) % n]
        p_curr = points[i]
        p_next = points[(i + 1) % n]

        dx1, dy1 = p_curr.x - p_prev.x, p_curr.y - p_prev.y
        dx2, dy2 = p_next.x - p_curr.x, p_next.y - p_curr.y

        l1 = math.sqrt(dx1**2 + dy1**2) or 1
        l2 = math.sqrt(dx2**2 + dy2**2) or 1

        nx1, ny1 = dy1/l1, -dx1/l1
        nx2, ny2 = dy2/l2, -dx2/l2

        avg_nx = (nx1 + nx2) / 2
        avg_ny = (ny1 + ny2) / 2
        l = math.sqrt(avg_nx**2 + avg_ny**2) or 1

        result.append(MapCord(
            p_curr.x + distance * avg_nx / l,
            p_curr.y + distance * avg_ny / l
        ))
    return result


def _detect_offset_sign(points, grid, ocean_hexes, test_dist=10):
    """Determine which sign of offset pushes toward the ocean interior."""
    n = len(points)
    if n < 10: return 1

    # Use centroid of boundary path as proxy for ocean interior
    cx = sum(p.x for p in points) / n
    cy = sum(p.y for p in points) / n

    # Sample some points, offset both ways, see which is closer to centroid
    step = max(1, n // 8)
    pos_score, neg_score = 0, 0

    pos_pts = offset_path(points, test_dist)
    neg_pts = offset_path(points, -test_dist)

    for i in range(0, n, step):
        dp = (pos_pts[i].x - cx)**2 + (pos_pts[i].y - cy)**2
        dn = (neg_pts[i].x - cx)**2 + (neg_pts[i].y - cy)**2
        if dp < dn:
            pos_score += 1
        else:
            neg_score += 1

    return 1 if pos_score >= neg_score else -1



def wave_svg_path(points, amplitude, wavelength, phase=0):
    """Generate SVG path 'd' string from points with sine perturbation along normals."""
    n = len(points)
    if n < 3: return ""

    cum_dist = 0
    coords = []

    for i in range(n):
        if i > 0:
            dx = points[i].x - points[i-1].x
            dy = points[i].y - points[i-1].y
            cum_dist += math.sqrt(dx**2 + dy**2)

        p_prev = points[(i - 1) % n]
        p_next = points[(i + 1) % n]
        dx = p_next.x - p_prev.x
        dy = p_next.y - p_prev.y
        l = math.sqrt(dx**2 + dy**2) or 1
        nx, ny = dy/l, -dx/l

        wave = amplitude * math.sin(2 * math.pi * cum_dist / wavelength + phase)
        coords.append(MapCord(points[i].x + wave * nx, points[i].y + wave * ny))

    d = f"M {coords[0].x:.1f},{coords[0].y:.1f}"
    for c in coords[1:]:
        d += f" L {c.x:.1f},{c.y:.1f}"
    return d


def OceanWaveOverlay(
    num_waves=5,
    spacing=8,
    amplitude_start=3.0,
    amplitude_decay=0.6,
    wavelength=40,
    stroke_color="#4a7fb5",
    opacity_start=0.5,
    opacity_decay=0.7,
    stroke_width=1.2,
    edge_fn=None,
    **kw
) -> OverlaySpec:
    """Ocean wave lines that follow the coastline and fade outward into the sea."""

    def render(ctx) -> str:
        terrain = ctx.terrain
        grid = ctx.grid

        # 1. Ocean region
        ocean_hexes = {i for i, e in enumerate(terrain.elevations) if e <= 0}
        if not ocean_hexes:
            return ""
        ocean_region = HexRegion(hexes=ocean_hexes, hexGrid=grid)

        borders = {}
        dummy_style = StyleCSS("_wave_boundary", fill="none", stroke="none")
        coast_paths = ocean_region.trace_perimeter_cached(
            borders=borders, f=edge_fn, style=dummy_style
        )
        if not coast_paths:
            return ""

        # 2. Clip path from ocean boundary
        clip_parts = []
        for cp in coast_paths:
            pts = cp.points
            if not pts: continue
            d = f"M {pts[0].x:.1f},{pts[0].y:.1f}"
            for p in pts[1:]:
                d += f" L {p.x:.1f},{p.y:.1f}"
            d += " Z"
            clip_parts.append(d)

        clip_d = " ".join(clip_parts)
        #clip_svg = f'<clipPath id="ocean-wave-clip"><path d="{clip_d}"/></clipPath>'
        #ctx.builder.add_definition(SVGDef("clipPath", "ocean-wave-clip", clip_svg, raw=True))

        # 3. Register wave styles
        amp = amplitude_start
        opacity = opacity_start
        for w in range(num_waves):
            style = StyleCSS(
                f"ocean_wave_{w}",
                fill="none",
                stroke=stroke_color,
                stroke_width=stroke_width,
                opacity=round(opacity, 3),
                stroke_linecap="round"
            )
            ctx.builder.add_style(style)
            amp *= amplitude_decay
            opacity *= opacity_decay

        # 4. Generate wave lines
        #svg_parts = ['<g clip-path="url(#ocean-wave-clip)">']
        svg_parts = ['<g>']

        coast_paths = join_paths(coast_paths, tolerance=grid.radius * 0.5)

        for coast_path in coast_paths:
            pts = coast_path.points
            if len(pts) < 3: continue

            # Smooth the coastline to remove hex-corner artifacts
            smoothed = coast_path.smooth(iterations=3)
            pts = smoothed.points
            
            # Auto-detect which direction is "into the ocean"
            sign = _detect_offset_sign(pts, grid, ocean_hexes, test_dist=spacing * 2)
            
            amp = amplitude_start
            for w in range(num_waves):
                dist = sign * spacing * (w + 1)
                offset_pts = offset_path(pts, dist)
                phase = w * 1.2

                d = wave_svg_path(offset_pts, amp, wavelength, phase)
                if d:
                    svg_parts.append(f'<path d="{d}" class="ocean_wave_{w}"/>')

                amp *= amplitude_decay

        svg_parts.append('</g>')
        return '\n'.join(svg_parts)

    return OverlaySpec("ocean_waves", render, priority=20)

